using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Controls.Primitives;using System.Windows.Input;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using TrayLeaf;
class Version113Tests {
 static int pass,fail;static Controller c;static Window w;static BindingFlags inst=BindingFlags.Instance|BindingFlags.NonPublic,stat=BindingFlags.Static|BindingFlags.NonPublic;
 static void Check(bool ok,string name){Console.WriteLine((ok?"PASS ":"FAIL ")+name);if(ok)pass++;else fail++;}
 static void Pump(int ms=60){var f=new DispatcherFrame();var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};t.Tick+=delegate{t.Stop();f.Continue=false;};t.Start();Dispatcher.PushFrame(f);}
 static IEnumerable<T> Find<T>(DependencyObject o)where T:DependencyObject{if(o is T)yield return(T)o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var x in Find<T>(VisualTreeHelper.GetChild(o,i)))yield return x;}
 static object Call(string name,params object[] a){return typeof(Controller).GetMethod(name,inst).Invoke(c,a);}
 static T El<T>(string name)where T:class{return w.FindName(name)as T;}
 static void Await(Task task){var end=DateTime.UtcNow.AddSeconds(10);while(!task.IsCompleted&&DateTime.UtcNow<end)Pump(10);if(!task.IsCompleted)throw new TimeoutException();task.GetAwaiter().GetResult();}
 static void Snapshot(Window d,string path){d.UpdateLayout();var b=new RenderTargetBitmap((int)Math.Ceiling(d.ActualWidth),(int)Math.Ceiling(d.ActualHeight),96,96,PixelFormats.Pbgra32);b.Render(d);var p=new PngBitmapEncoder();p.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(path))p.Save(f);}
 [STAThread]static int Main(string[] args){try{
  Directory.CreateDirectory(args[0]);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("TrayLeaf.MainWindow.xaml"))w=(Window)System.Windows.Markup.XamlReader.Load(s);
  using(var db=new Database(Path.Combine(args[0],"ui-"+Guid.NewGuid()+".db"))){c=new Controller(app,w,db,true);c.Start(null);Pump();SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(w.Dispatcher));
   Check(AppIdentity.ReleaseVersion=="1.1.3","version-113");
   db.SaveProfile("close","用户设置",new[]{new AppRow{Name="Sample",Path=@"C:\fixture\a.exe",Selected=true}}.ToList(),0);Call("ReloadCollections");Call("Navigate",2);Call("SelectSettings",5);Call("RefreshProfileLinks");UiLanguage.Set("en");Pump();
   var links=El<StackPanel>("ProfileLinksHost");var linked=Find<ComboBox>(links).First();Check(linked.SelectedItem.ToString()=="Not linked","english-unlinked-sentinel");Check(!linked.SelectedItem.ToString().Contains("0 item"),"unlinked-sentinel-has-no-count");Check(Find<TextBlock>(links).Any(t=>t.Text=="用户设置"),"profile-user-name-not-translated");
   Check(UiLanguage.Text("单击切换升序 / 降序；拖动列边界调整宽度")=="Click to sort; drag a column edge to resize","english-column-tooltip");
   Call("Navigate",0);UiLanguage.Set("zh-Hans");var profiles=El<ComboBox>("CloseProfileCombo");int calls=0;var configure=typeof(Controller).GetMethod("ConfigureProfileSelection",stat);var probe=new ComboBox{ItemsSource=new[]{"first","second"},SelectedIndex=0,Width=200};var host=new Window{Owner=w,Content=probe,Width=260,Height=160};configure.Invoke(null,new object[]{probe,new Action(()=>calls++)});host.Show();Pump();calls=0;probe.IsDropDownOpen=true;Pump();probe.IsDropDownOpen=false;Pump();Check(calls==0,"outside-dismiss-does-not-apply-profile");
   probe.IsDropDownOpen=true;Pump();probe.SelectedIndex=1;probe.IsDropDownOpen=false;Pump();Check(calls==0&&probe.SelectedIndex==0,"dismiss-reverts-keyboard-preview");
   probe.IsDropDownOpen=true;Pump();probe.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(host),0,Key.Enter){RoutedEvent=Keyboard.PreviewKeyDownEvent});probe.IsDropDownOpen=false;Pump();Check(calls==1,"enter-confirms-current-profile");
   probe.IsDropDownOpen=true;Pump();var container=(ComboBoxItem)probe.ItemContainerGenerator.ContainerFromIndex(0);container.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice,0,MouseButton.Left){RoutedEvent=Mouse.PreviewMouseUpEvent});probe.IsDropDownOpen=false;Pump();Check(calls==2,"click-current-item-reapplies-profile");host.Close();
   foreach(string lang in new[]{"zh-Hans","zh-Hant","en"})foreach(int mode in new[]{0,1}){UiLanguage.Set(lang);El<ComboBox>("ThemeInput").SelectedIndex=mode;Call("PreviewAppearance");var d=CloseWindowDialog.Build(w);d.Show();Pump();var panel=Find<StackPanel>(d).First();var root=(Panel)d.Content;Check(((SolidColorBrush)root.Background).Color==((SolidColorBrush)panel.Background).Color,"close-dialog-one-surface-"+lang+mode);Check(d.ActualWidth/d.ActualHeight>1.45&&d.ActualWidth/d.ActualHeight<2.7,"comfortable-close-proportion-"+lang+mode);if(lang=="en")Snapshot(d,Path.Combine(args[0],"close113-"+mode+".png"));d.Close();
    var confirm=ModernDialog.Build(w,UiLanguage.Text("请先保存工作,未保存的数据可能丢失！"),"",true,true);confirm.Show();Pump();var content=Find<StackPanel>(confirm).First();Check(((SolidColorBrush)((Panel)confirm.Content).Background).Color==((SolidColorBrush)content.Background).Color,"confirmation-one-surface-"+lang+mode);Check(confirm.ActualWidth/confirm.ActualHeight<2.7,"confirmation-proportion-"+lang+mode);confirm.Close();}
   UiLanguage.Set("zh-Hans");Call("PresentUpdate","1.1.5");Check(Convert.ToString(El<Button>("NewVersionBadge").Content)=="发现新版本 v1.1.5","header-includes-normalized-version");
   Check(El<Button>("DownloadLatestButton")==null||El<Button>("DownloadLatestButton").Visibility==Visibility.Collapsed,"header-has-no-download-action");Call("Navigate",3);Pump();var about=(FrameworkElement)w.FindName("AboutPanel");Check(Convert.ToString(El<Button>("CheckUpdateButton").Content)=="下载更新","about-check-becomes-download");
   var duplicate=typeof(Controller).GetField("downloadButton",inst);Check(duplicate==null||duplicate.GetValue(c)==null||((Button)duplicate.GetValue(c)).Visibility==Visibility.Collapsed,"no-extra-about-download-button");
   UiLanguage.Set("en");Check(Convert.ToString(El<Button>("CheckUpdateButton").Content)=="Download update","english-download-action");Check(Convert.ToString(El<Button>("NewVersionBadge").Content)=="Update available v1.1.5","english-version-badge");
   Call("PresentUpdate",AppIdentity.ReleaseVersion);Check(Convert.ToString(El<Button>("CheckUpdateButton").Content)=="Check for updates"&&El<Button>("NewVersionBadge").Visibility==Visibility.Collapsed,"up-to-date-restores-check-action");
   Call("PresentUpdate","v9.0.0");int fetched=0;typeof(Controller).GetField("releaseFetcher",inst).SetValue(c,new Func<CancellationToken,Task<ReleaseInfo>>(token=>{fetched++;throw new IOException("offline fixture");}));typeof(Controller).GetField("reportUpdateError",inst).SetValue(c,new Action<string>(s=>{}));El<Button>("CheckUpdateButton").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Check(fetched==1,"about-action-invokes-download-flow");
   Call("Navigate",2);Call("SelectSettings",2);Pump();El<Button>("SettingsProfiles").Focus();Pump();var bd=(Border)El<Button>("SettingsProfiles").Template.FindName("Bd",El<Button>("SettingsProfiles"));Check(((SolidColorBrush)bd.BorderBrush).Color!=((SolidColorBrush)w.Resources["Accent"]).Color,"focus-does-not-look-like-selected-nav");
   foreach(string name in new[]{"MinimizeWindow","MaximizeWindow","CloseWindow"}){var b=El<Button>(name);b.Focus();Pump();var border=(Border)b.Template.FindName("CaptionSurface",b);Check(((SolidColorBrush)border.BorderBrush).Color.A==0,"caption-never-draws-focus-box-"+name);}
   var scroller=El<ScrollViewer>("SettingsPanel");scroller.Focus();Pump();Check(scroller.FocusVisualStyle==null,"settings-no-dotted-focus-adorner");
   UiLanguage.Set("en");Call("SelectSettings",5);Pump();Snapshot(w,Path.Combine(args[0],"english-profiles113.png"));Call("Navigate",3);Pump();Snapshot(w,Path.Combine(args[0],"about113.png"));typeof(Controller).GetField("exiting",inst).SetValue(c,true);w.Close();
  }Console.WriteLine("RESULT "+pass+" passed "+fail+" failed");return fail==0?0:1;
 }catch(Exception ex){Console.WriteLine("ERROR "+ex);return 2;}}
}
